head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > E > onfooterclick]<br/>Footer 영역을 마우스 왼쪽 버튼으로 클릭할 때 발생합니다.",
    "validation" : [
        "Footer 영역을 마우스 왼쪽 버튼으로 클릭할 때 onfooterclick 이벤트가 발생해야 합니다.",
        "footerId 파라미터로 클릭된 Footer 영역의 Cell ID 가 전달되어야 합니다.",
        "focusFooter=true 일때 onfooterclick 이벤트 발생 전 Footer Cell 포커스가 발생하므로 이벤트 핸들러에서 getFocusedFooterCell() 등의 메소드로 포커스된 Footer Cell 정보를 조회할 수 있습니다.",        
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // dataList 생성
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // 조건 설정
    //  - con_focusFooter 가 미설정('') 이면 focusFooter 속성을 부여하지 않음(기본값 false 동작)
    //  - 'true' / 'false' 면 해당 값으로 속성 부여
    //  - con_ 옵션은 공통 gdl_boolean 사용 → value(1/2/3) 가 아닌 getText() 로 label(true/false) 을 가져옴
    let focusFooterVal = con_focusFooter.getText();

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    let lblFocusFooter = (focusFooterVal === '') ? '미설정(기본값 false)' : focusFooterVal;
    $c.gcm.createLabel('label="focusFooter=' + lblFocusFooter + ' 로 GridView 생성 (Footer 1행 ft1~ft4). Footer Cell 을 마우스 왼쪽 버튼으로 클릭하여 onfooterclick 발생 확인"', '', 'label1');

    // Property 설정은 createCList 공통 함수 사용
    //  - focusFooter 미설정이면 properties 에 포함하지 않아 기본값(false) 동작
    let properties = {
        dataList: "data:dlt_bind",
        checkAllType: "false",
        useShiftKey: "true",
        useCtrlKey: "true",
        selectedCellColor: "#1565c0",
        selectedRowColor: "#bbdefb",
    };
    if (focusFooterVal !== '') {
        properties.focusFooter = focusFooterVal;
    }
    let cList = $c.gcm.createCList(properties);

    // 이벤트 바인딩은 createEList 공통 함수 사용
    let eList = $c.gcm.createEList(["onfooterclick"]);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // target 생성 (Header 4컬럼 + gBody + Footer 1행, Footer Cell ft1~ft4)
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' ' + eList + ' id="" style="width:520px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="onfooterclick 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column1" value="구분"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column2" value="금액"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column3" value="수량"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column4" value="비고"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="130" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '<w2:footer style="" id="footer1">';
    strTarget += '<w2:row style="" id="row3">';
    strTarget += '<w2:column width="130" style="" inputType="text" id="ft1" value="합계"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="ft2" value="footer2"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="ft3" value="footer3"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="ft4" value="footer4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:footer>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// onfooterclick : Footer Cell 을 마우스 왼쪽 버튼으로 클릭할 때 발생
//  - footerId : 클릭된 Footer 영역의 Cell ID
//  - @spec : focusFooter=true 일때 이벤트 발생 전 Footer Cell 포커스가 발생하므로
//            핸들러 안에서 getFocusedFooterCell() 로 포커스된 Footer Cell 을 조회할 수 있음
scwin.target1_onfooterclick = function (footerId) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onfooterclick=====");
    wf_body_bottom.getObj("scwin").setReturnValue("footerId : " + footerId);

    // @spec 확인 : 이벤트 발생 시점에 이미 포커스된 Footer Cell 정보를 조회
    //  (focusFooter=true 면 클릭된 Cell 정보 반환, false/미설정이면 빈 배열)
    let focused = target1.getFocusedFooterCell();
    let result = '';
    if (focused && focused.length > 0) {
        for (let i = 0; i < focused.length; i++) {
            result += '{id:"' + focused[i].id + '", rowIndex:' + focused[i].rowIndex + ', colIndex:' + focused[i].colIndex + '}';
            if (i < focused.length - 1) {
                result += ', ';
            }
        }
        result = '[' + result + ']';
    } else {
        result = '[] (포커스된 Footer Cell 없음)';
    }
    wf_body_bottom.getObj("scwin").setReturnValue("getFocusedFooterCell : " + result);
}
